def verify_isbn(isbn: str) -> str:

    checksum = sum([9, 8, 7, 6, 5, 4, 3, 2, 1])
    isbn_list = isbn.split('-')
    for i in range(len(isbn_list)):
        checksum += int(isbn_list[i][i % 2])

