def generate_numbers(n, rules):
    unique_nums = set()
    queue = []
    queue.append(n)
    while queue:
        curr_num = queue.pop(0)
        if curr_num not in unique_nums:
            unique_nums.add(curr_num)
            for rule in rules:
                new_num = list(str(curr_num))
                for i, num in enumerate(new_num):
                    if num == rule[0]:
                        new_num[i] = rule[1]
                queue.append(int("".join(new_num)))
    return len(unique_nums)
